<?php
require_once __DIR__ . '/../database/database.php'; require_once __DIR__ . '/../app/auth.php'; require_once __DIR__ . '/../app/layout.php'; requireLogin();
$stmt=$pdo->prepare('SELECT s.*,p.name AS project_name FROM sessions s JOIN projects p ON p.id=s.project_id WHERE p.user_id=? ORDER BY COALESCE(s.ended_at,s.started_at) DESC');$stmt->execute([$_SESSION['user_id']]);$sessions=$stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sessions | Project Continuum</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><div class="app-shell"><?php renderSidebar('sessions');?><main class="main-content"><header class="page-header"><div><h1>Work Sessions</h1><p>Your record of progress, decisions, and where to continue.</p></div></header><section class="project-cards"><?php if($sessions):foreach($sessions as $s):$duration=(($s['ended_at']?strtotime($s['ended_at']):time())-strtotime($s['started_at']));$durationLabel=floor($duration/3600)?floor($duration/3600).'h '.floor(($duration%3600)/60).'m':floor($duration/60).'m';?><a class="card project-card" href="session.php?id=<?=(int)$s['id']?>"><div class="project-icon">◷</div><div><h3><?=htmlspecialchars($s['project_name'])?></h3><p><?=htmlspecialchars($s['next_step']?:$s['objective']?:'No continuity note saved yet.')?></p><span class="metadata"><?=date('M j, Y · g:i A',strtotime($s['started_at']))?> · <?= $durationLabel ?></span></div><div class="progress"><span class="badge <?=$s['ended_at']?'completed':'in-progress'?>"><?=$s['ended_at']?'Finished':'Active'?></span></div></a><?php endforeach;else:?><div class="card panel"><p class="empty">No sessions yet. Open a project and choose “Start a work session.”</p></div><?php endif;?></section></main></div></body></html>
